#!/usr/bin/env python3
"""Bounded, independent SI-unit boundary critical-speed audit; no solver edits."""
import os
for k in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS']:
    os.environ[k]='1'
from pathlib import Path
import numpy as np
import csv,json,hashlib,datetime as dt
BASE=Path(__file__).resolve().parent
ROOT=BASE.parent
MP=1.67262192369e-27;KB=1.380649e-23;MU0=1.25663706212e-6
AU_KM=149597870.7;DAY_S=86400.;GAMMA=1.5
meta=json.loads((ROOT/'inputs/metadata.json').read_text())
r0=meta['r0_au'];omega=meta['rotation_rad_day']
source=ROOT/'inputs/boundary_map.csv'
a=np.loadtxt(source,delimiter=',',skiprows=1)
times=np.unique(a[:,0]);lats=np.unique(a[:,2]);lons=np.unique(a[:,1])
assert len(a)==len(times)*len(lats)*len(lons)
a=a.reshape(len(times),len(lats),len(lons),7)
assert np.all(a[:,:,:,0]==times[:,None,None])
assert np.all(a[:,:,:,1]==lons[None,None,:])
assert np.all(a[:,:,:,2]==lats[None,:,None])
speed=a[:,:,:,3];density=a[:,:,:,4];br=a[:,:,:,5];temperature=a[:,:,:,6]
assert np.all(np.isfinite(a)) and np.all(speed>0) and np.all(density>0) and np.all(temperature>0)
z=np.load(BASE/'induction_audit/boundary_inductive.npz')
assert np.allclose(times,z['day'],rtol=0,atol=1e-8)
assert np.allclose(speed,z['speed_kms'],rtol=0,atol=1e-10)
assert np.allclose(density,z['density_1au_cm3'],rtol=0,atol=1e-10)
assert np.allclose(temperature,z['temperature_K'],rtol=0,atol=1e-10)
br_corr=z['br_1au_nt'];etheta=z['emf_theta_nT_AU_day'];ephi=z['emf_phi_nT_AU_day']
lat_edges=np.r_[-np.pi/2,.5*(lats[:-1]+lats[1:]),np.pi/2]
BANDS={'lat_pm60':(-60,60),'lat_pm30':(-30,30),'comet_source_lat_m15_0':(-15,0)}
PERIODS={'early_Nov10_24':(9.,24.),'late_Nov25_Dec04':(24.,34.),'all_Nov10_Dec04':(9.,34.)}
AREA={}
for name,(lo,hi) in BANDS.items():
    lo,hi=np.deg2rad([lo,hi]);left=np.clip(lat_edges[:-1],lo,hi);right=np.clip(lat_edges[1:],lo,hi)
    AREA[name]=np.maximum(0,np.sin(right)-np.sin(left))
    assert abs(AREA[name].sum()-(np.sin(hi)-np.sin(lo)))<1e-12

def map_time_weights(start,end):
    """Integrate linear temporal basis exactly, with source's endpoint clamps."""
    out=np.zeros(len(times));knots=np.r_[start,times[(times>start)&(times<end)],end]
    for left,right in zip(knots[:-1],knots[1:]):
        mid=.5*(left+right);h=right-left
        if mid<times[0]:out[0]+=h
        elif mid>=times[-1]:out[-1]+=h
        else:
            i=np.searchsorted(times,mid)-1;f=.5*((left-times[i])+(right-times[i]))/(times[i+1]-times[i]);out[i]+=h*(1-f);out[i+1]+=h*f
    assert abs(out.sum()-(end-start))<1e-12
    return out

def state(v,n1,b1,temp,et=None,ep=None):
    """Input v km/s,n1 cm^-3 at1AU,b1 nT at1AU,T K; return SI-derived km/s modes."""
    n=n1/r0**2;rho=MP*n*1e6;pressure=2*n*1e6*KB*temp
    br0=b1/r0**2
    v_au_day=v*DAY_S/AU_KM
    bp=-omega*r0*np.cos(lats[:,None])*br0/v_au_day
    bt=np.zeros_like(bp)
    if et is not None:bp=bp+et/v_au_day;bt=-ep/v_au_day
    b2=(br0*br0+bp*bp+bt*bt)*1e-18
    sound2=GAMMA*pressure/rho/1e6
    va2=b2/(MU0*rho)/1e6;var2=(br0*1e-9)**2/(MU0*rho)/1e6
    disc=np.maximum(0,(sound2+va2)**2-4*sound2*var2)
    cf2=.5*(sound2+va2+np.sqrt(disc))
    slow2=np.maximum(0,sound2*var2/cf2)
    cf=np.sqrt(cf2);var=np.sqrt(var2);slow=np.sqrt(slow2)
    return {'mach_fast':v/cf,'cf_radial_kms':cf,'sound_speed_kms':np.sqrt(sound2),'va_radial_kms':var,'va_total_kms':np.sqrt(va2),'slow_radial_kms':slow,'Br_nT':br0,'Btheta_nT':bt,'Bphi_nT':bp,'Btotal_nT':np.sqrt(b2)*1e9,'pressure_nPa':pressure*1e9,'density_r0_cm3':n,'speed_kms':v,'temperature_K':temp,'incoming_to_sun_characteristic_count':(v<cf).astype(int)+(v<var).astype(int)+(v<slow).astype(int)}

# Algebraic directional limits and dimensional consistency, independent of map values.
for sound2,va2 in [(4.,9.),(16.,1.),(9.,9.)]:
    parallel=.5*(sound2+va2+np.sqrt((sound2+va2)**2-4*sound2*va2))
    perpendicular=.5*(sound2+va2+abs(sound2+va2))
    assert abs(parallel-max(sound2,va2))<1e-12
    assert abs(perpendicular-(sound2+va2))<1e-12
# CSV calibrations imply speed/sound-speed constant to printed precision.
sound_direct=np.sqrt(2*GAMMA*KB*temperature/MP)/1000
assert np.max(np.abs(sound_direct/np.sqrt(GAMMA*(2*density/r0**2*1e6*KB*temperature)/(MP*density/r0**2*1e6))/1000-1))<1e-12

def quantile(x,w):
    m=w>0;x=x[m];w=w[m];order=np.argsort(x);x=x[order];w=w[order]
    u=(np.cumsum(w)-.5*w)/w.sum();qs=[0,.01,.05,.16,.5,.84,.95,.99,1]
    return dict(zip(['min','p01','p05','p16','p50','p84','p95','p99','max'],np.interp(qs,u,x).tolist()))

snapshots={'parker_raw_Br':state(speed,density,br,temperature),'parker_monopole_cleaned_Br':state(speed,density,br_corr,temperature),'inductive_centered_E':state(speed,density,br_corr,temperature,etheta,ephi)}
summary={};extremes=[]
for variant,fields in snapshots.items():
    summary[variant]={}
    for period,(start,end) in PERIODS.items():
        tw=map_time_weights(start,end);summary[variant][period]={}
        for band,lw in AREA.items():
            weights=np.broadcast_to(tw[:,None,None]*lw[None,:,None],speed.shape)
            total=weights.sum();m=weights>0
            d={'map_quadrature_subfast_area_time_fraction':float(np.sum(weights*(fields['mach_fast']<1))/total),'subalfvenic_radial_area_time_fraction':float(np.sum(weights*(speed<fields['va_radial_kms']))/total),'subslow_area_time_fraction':float(np.sum(weights*(speed<fields['slow_radial_kms']))/total),'mach_fast':quantile(fields['mach_fast'],weights),'cf_radial_kms':quantile(fields['cf_radial_kms'],weights),'speed_kms':quantile(speed,weights),'outgoing_physical_characteristic_count_fractions':{str(k):float(np.sum(weights*(fields['incoming_to_sun_characteristic_count']==k))/total) for k in range(4)}}
            summary[variant][period][band]=d
            for label,target in [('minimum_mach',np.where(m,fields['mach_fast'],np.inf)),('maximum_mach',np.where(m,-fields['mach_fast'],np.inf)),('maximum_cf',np.where(m,-fields['cf_radial_kms'],np.inf))]:
                i,j,k=np.unravel_index(np.argmin(target),target.shape)
                row={'variant':variant,'period':period,'band':band,'extreme':label,'map_day':float(times[i]),'utc':(dt.datetime(2025,11,1)+dt.timedelta(days=float(times[i]))).isoformat(),'carrington_lon_deg':float(np.rad2deg(lons[k])),'lat_deg':float(np.rad2deg(lats[j])),'density_1au_cm3':float(density[i,j,k]),'Br_1au_nT':float((br if variant=='parker_raw_Br' else br_corr)[i,j,k])}
                for name,values in fields.items():row[name]=float(values[i,j,k])
                extremes.append(row)

# Check true linear interpolation in primitive boundary fields. Longitude rotation
# leaves the full-longitude area integral unchanged, so no phase interpolation is needed.
def interpolated_fractions(step_hours):
    result={}
    for period,(start,end) in PERIODS.items():
        h=step_hours/24;nt=int(round((end-start)/h));out={v:{b:np.zeros(3) for b in AREA} for v in snapshots}
        for t in start+(np.arange(nt)+.5)*h:
            if t<=times[0]:i=0;f=0.
            elif t>=times[-1]:i=len(times)-2;f=1.
            else:i=np.searchsorted(times,t)-1;f=(t-times[i])/(times[i+1]-times[i])
            def interp(field):return (1-f)*field[i]+f*field[i+1]
            v,n,temp=interp(speed),interp(density),interp(temperature)
            ei=None if t<times[0] or t>=times[-1] else max(0,np.searchsorted(times,t,side='right')-1)
            for variant in snapshots:
                clean=variant!='parker_raw_Br';b=interp(br_corr if clean else br)
                if variant=='inductive_centered_E':
                    et=np.zeros_like(b) if ei is None else etheta[ei];ep=np.zeros_like(b) if ei is None else ephi[ei]
                else:et=ep=None
                s=state(v,n,b,temp,et,ep)
                flags=[s['mach_fast']<1,v<s['va_radial_kms'],v<s['slow_radial_kms']]
                for band,lw in AREA.items():
                    norm=len(lons)*lw.sum()
                    out[variant][band]+=np.array([np.sum(lw[:,None]*flag)/norm for flag in flags])/nt
        result[period]={variant:{band:{'subfast':float(values[0]),'subalfvenic_radial':float(values[1]),'subslow':float(values[2])} for band,values in bands.items()} for variant,bands in out.items()}
    return result
interp_hourly=interpolated_fractions(1.)
interp_halfhour=interpolated_fractions(.5)
for variant in summary:
 for period in PERIODS:
  for band in BANDS:
   summary[variant][period][band]['interpolated_hourly_fraction']=interp_hourly[period][variant][band]
   summary[variant][period][band]['interpolated_halfhourly_fraction']=interp_halfhour[period][variant][band]

out={'author':'Codex-external_model','created_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'r0_au':r0,'gamma':GAMMA,'pressure_factor':2,'mass_density':'proton only:mp*np','rotation_rad_day':omega,'source_surface_au':0,'source_shape':list(speed.shape),'formula':'a2=gamma*p/rho;vA2=|B|2/(mu0*rho);vAr2=Br2/(mu0*rho);cf_radial2=(a2+vA2+sqrt((a2+vA2)^2-4*a2*vAr2))/2;Mach=vr/cf_radial','periods_day_since_Nov1':PERIODS,'bands_deg':BANDS,'time_weighting':'Native snapshot quadrature integrates linear temporal basis over full calendar windows; actual primitive-interpolated fractions checked at hourly and half-hourly midpoints. Endpoint clamps match prescribed boundary. Quantiles refer to weighted native map states, not all interpolated states.','latitude_weighting':'Exact spherical-cell sin(latitude_upper)-sin(latitude_lower), clipped to requested band; all longitudes equally weighted. Half of the -15deg-centered cell belongs to[-15,0].','endpoint_clamp_days':{'before_first_map':float(times[0]-9),'after_final_map':float(34-times[-1])},'optional_E':'Monopole-cleaned Br and centered EMFs from own NPZ; Etheta contributes+Bphi, Ephi contributes-Btheta, dividing E[nT AU/day] by vr[AU/day]. E uses left interval, zero outside range.','source_files':[],'results':summary,'extremes':extremes,'primary_characteristic_reference':'https://doi.org/10.1051/0004-6361/202244665','limitations':['This diagnoses prescribed boundary states, not the evolved wind or causal reach to comet.','Full-longitude source-band fractions are not weighting along the actual comet source trajectory.','Subfast inflow permits at least one physical characteristic to travel toward the inner boundary; fixing all flux components bypasses that feedback and is a modeling assumption.','GLM cleaning characteristics are not counted as physical MHD modes.','Quantiles use map-snapshot quadrature; explicit hourly/half-hourly fractions sample temporal interpolation.','No new forward simulations or primary solver edits.']}
for path in [source,ROOT/'inputs/metadata.json',BASE/'induction_audit/boundary_inductive.npz',Path(__file__)]:
    b=path.read_bytes();out['source_files'].append({'path':str(path),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
(BASE/'inner_mach_audit.json').write_text(json.dumps(out,indent=2))
with (BASE/'inner_mach_audit_extremes.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(extremes[0]));w.writeheader();w.writerows(extremes)
for variant in summary:
 print(variant)
 for period in PERIODS:
  for band,d in summary[variant][period].items():print(period,band,'mapfraction',round(d['map_quadrature_subfast_area_time_fraction'],6),'halfhr',d['interpolated_halfhourly_fraction'],'M[0,5,50,95,100]',[round(d['mach_fast'][k],4) for k in ['min','p05','p50','p95','max']])
